3	import java.math.BigDecimal;
4	import java.util.Arrays;
5	import java.util.List;
6	import java.util.Optional;
7	import org.springframework.stereotype.Service;
8	
9	@Service
10	public class ResumoService {
11	
12	    public ResumoResponse calcular(ResumoRequest req) {
13	        List<ItemPedido> itens = validarItens(req.itens());
14	        BigDecimal subtotal = itens.stream().map(item -> item.subtotal()).reduce(Dinheiro.ZERO, BigDecimal::add);
15	        BigDecimal peso = itens.stream().map(item -> item.peso()).reduce(BigDecimal.ZERO, BigDecimal::add);
16	
17	        NivelClube nivel = buscar(NivelClube.values(), req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
18	        Regiao regiao = buscar(Regiao.values(), req.regiao(), "REGIAO_INVALIDA");
19	        ModalidadeEntrega modalidade = buscar(ModalidadeEntrega.values(), req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
20	        if (!modalidade.disponivel(peso)) {
21	            throw new ResumoException("MODALIDADE_INDISPONIVEL");
22	        }
23	
24	        BigDecimal frete = nivel.temFreteGratis() ? Dinheiro.ZERO : modalidade.frete(peso);
25	        Pedido pedido = new Pedido(itens, subtotal, frete);
26	        BigDecimal desconto = Optional.ofNullable(req.cupom())
27	                .filter(codigo -> !codigo.isBlank())
28	                .map(codigo -> descontoDoCupom(codigo, pedido))
29	                .orElse(Dinheiro.ZERO);
30	
31	        BigDecimal seguro = regiao.seguro(subtotal);
32	        BigDecimal totalPedido = subtotal.subtract(desconto).add(frete).add(seguro);
33	
34	        FormaPagamento forma = buscar(FormaPagamento.values(), req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
35	        int parcelas = Optional.ofNullable(req.parcelas()).orElse(1);
36	        if (!forma.parcelasPermitidas(parcelas)) {
37	            throw new ResumoException("PARCELAMENTO_INVALIDO");
38	        }
39	        if (!forma.disponivel(totalPedido)) {
40	            throw new ResumoException("FORMA_PAGAMENTO_INDISPONIVEL");
41	        }
42	        Pagamento pagamento = forma.calcular(totalPedido, parcelas);
43	
44	        return new ResumoResponse(
45	                subtotal,
46	                desconto,
47	                frete,
48	                modalidade.prazoDias(),
49	                seguro,
50	                pagamento.totalFinal().subtract(totalPedido),
51	                pagamento.totalFinal(),
52	                pagamento.parcelas(),
53	                pagamento.valorParcela(),
54	                nivel.credito(subtotal),
55	                nivel.temBrinde(subtotal));
56	    }
57	
58	    private static List<ItemPedido> validarItens(List<ResumoRequest.Item> itens) {
59	        if (itens == null || itens.isEmpty()) {
60	            throw new ResumoException("PEDIDO_INVALIDO");
61	        }
62	        return itens.stream().map(ResumoService::validarItem).toList();
63	    }
64	
65	    private static ItemPedido validarItem(ResumoRequest.Item item) {
66	        if (item == null
67	                || !positivo(item.precoUnitario())
68	                || item.quantidade() == null || item.quantidade() <= 0
69	                || !positivo(item.pesoKg())) {
70	            throw new ResumoException("PEDIDO_INVALIDO");
71	        }
72	        return new ItemPedido(item.precoUnitario(), item.quantidade(), item.pesoKg());
73	    }
74	
75	    private static boolean positivo(BigDecimal valor) {
76	        return valor != null && valor.signum() > 0;
77	    }
78	
79	    private static BigDecimal descontoDoCupom(String codigo, Pedido pedido) {
80	        Cupom cupom = buscar(Cupom.values(), codigo, "CUPOM_INVALIDO");
81	        if (!cupom.aplicavel(pedido)) {
82	            throw new ResumoException("CUPOM_NAO_APLICAVEL");
83	        }
84	        return cupom.desconto(pedido);
85	    }
86	
87	    private static <E extends Enum<E>> E buscar(E[] valores, String codigo, String erro) {
88	        return Arrays.stream(valores)
89	                .filter(valor -> valor.name().equals(codigo))
90	                .findFirst()
91	                .orElseThrow(() -> new ResumoException(erro));
92	    }
93	}
