1	package com.loja.checkout;
2	
3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	import java.math.RoundingMode;
6	
7	enum FormaPagamento {
8	
9	    PIX {
10	        boolean parcelasPermitidas(int parcelas) {
11	            return parcelas == 1;
12	        }
13	
14	        Pagamento calcular(BigDecimal total, int parcelas) {
15	            BigDecimal totalFinal = total.subtract(Dinheiro.centavos(total.multiply(new BigDecimal("0.05"))));
16	            return new Pagamento(totalFinal, 1, totalFinal);
17	        }
18	    },
19	
20	    BOLETO {
21	        boolean parcelasPermitidas(int parcelas) {
22	            return parcelas == 1;
23	        }
24	
25	        boolean disponivel(BigDecimal total) {
26	            return total.compareTo(new BigDecimal("1000")) <= 0;
27	        }
28	
29	        Pagamento calcular(BigDecimal total, int parcelas) {
30	            BigDecimal totalFinal = total.add(Dinheiro.centavos(new BigDecimal("3.49")));
31	            return new Pagamento(totalFinal, 1, totalFinal);
32	        }
33	    },
34	
35	    CARTAO {
36	        boolean parcelasPermitidas(int parcelas) {
37	            return parcelas >= 1 && parcelas <= 12;
38	        }
39	
40	        Pagamento calcular(BigDecimal total, int parcelas) {
41	            if (parcelas <= 3) {
42	                BigDecimal parcela = total.divide(BigDecimal.valueOf(parcelas), 2, RoundingMode.HALF_EVEN);
43	                return new Pagamento(total, parcelas, parcela);
44	            }
45	            BigDecimal taxa = new BigDecimal("0.0199");
46	            BigDecimal inverso = BigDecimal.ONE.divide(BigDecimal.ONE.add(taxa).pow(parcelas), MathContext.DECIMAL128);
47	            BigDecimal parcela = Dinheiro.centavos(
48	                    total.multiply(taxa).divide(BigDecimal.ONE.subtract(inverso), MathContext.DECIMAL128));
49	            return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcelas, parcela);
50	        }
51	    };
52	
53	    abstract boolean parcelasPermitidas(int parcelas);
54	
55	    abstract Pagamento calcular(BigDecimal total, int parcelas);
56	
57	    boolean disponivel(BigDecimal total) {
58	        return true;
59	    }
60	}
