        List<ResumoRequest.Item> itens = List.of(
                new ResumoRequest.Item("Sofá", new BigDecimal("900.00"), 1, new BigDecimal("6.00")));

        assertErro("MODALIDADE_INDISPONIVEL", new ResumoRequest(itens, "MOTOBOY", null, "PIX", null, "BRONZE", "SUL"));
